-- =====================================================================
-- RP_OWNER_CURRENT_SEED_DATA.sql
-- Data snapshot exported from the live rp-oracle docker RP_OWNER schema.
-- Tables are loaded in alphabetical order (not FK-dependency order), so
-- all foreign key constraints are disabled before loading and re-enabled
-- afterward to avoid parent-key-not-found errors on the load order.
--
-- Usage:
--   sqlplus RP_OWNER/RPOwner123@<destination>:1521/XEPDB1 @RP_OWNER_CURRENT_SEED_DATA.sql
-- Run AFTER RP_OWNER_FULL_DDL_EXPORT.sql has created the schema.
-- =====================================================================

PROMPT Disabling all FK constraints for bulk load...
BEGIN
  FOR r IN (SELECT table_name, constraint_name FROM user_constraints WHERE constraint_type = 'R') LOOP
    BEGIN
      EXECUTE IMMEDIATE 'ALTER TABLE "' || r.table_name || '" DISABLE CONSTRAINT "' || r.constraint_name || '"';
    EXCEPTION WHEN OTHERS THEN
      DBMS_OUTPUT.PUT_LINE('  could not disable ' || r.constraint_name || ' on ' || r.table_name || ': ' || SQLERRM);
    END;
  END LOOP;
END;
/

