INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7875,954,'Theme 02','Innovation','AP05','Artificial Intelligence','KPI','Regular','05.01.04','Denominator','Total MSME loan applications submitted in the reporting period','Banks to only report this figure if it has mentioned credit assessment, underwriting and memorandum generation as an AI use case in Appendix 05.01.04','Number (Integer)','12782',NULL,'MSME');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7876,955,'Theme 02','Innovation','AP05','Artificial Intelligence','KPI','Regular','05.01.04','Denominator 1','Of which, MSME loan applications for which credit underwriting and memo generation was undertaken through AI tool',NULL,'Number (Integer)','0',NULL,'MSME');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7877,956,'Theme 02','Innovation','AP05','Artificial Intelligence','KPI','Regular','05.01.04','Numerator','Of which, MSME loan applications for which credit underwriting and memo generation was done successfully through AI tool',NULL,'Number (Integer)','0',NULL,'MSME');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7878,957,'Theme 02','Innovation','AP05','Artificial Intelligence',NULL,'Regular','05.01.04','Numerator 1','Of which, count of MSME loan applications where there was a techincal decline in the generated credit memo','Bank should report the % of eligible cases where the deployed AI solution failed to complete data ingestion, reading, extraction, or structuring of information from uploaded source documents due to technical reasons etc.','Formula summation','0',NULL,'MSME');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7879,958,'Theme 02','Innovation','AP05','Artificial Intelligence','KPI','Regular','05.01.04','(i)','Credit assessment and processing use cases','Bank should report the % of eligible cases where the deployed AI solution failed to complete data ingestion, reading, extraction, or structuring of information from uploaded source documents due to technical reasons','Number (Integer)','0',NULL,'MSME');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7880,959,'Theme 02','Innovation','AP05','Artificial Intelligence','KPI','Regular','05.01.04','(ii)','AI driven Business, financial, and applicant analysis','Bank should report the % of eligible cases where the deployed AI solution failed to generate the required business, financial, or applicant analysis due to technical reasons (e.g.model runtime failure, incomplete generation due to system error etc.)','Number (Integer)','0',NULL,'MSME');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7881,960,'Theme 02','Innovation','AP05','Artificial Intelligence','KPI','Regular','05.01.04','(iii)','AI driven computation of metrics, trends, and sectoral benchmarking','Bank should report the % of eligible cases where the deployed AI solution failed to compute financial metrics, trends, or sectoral / peer benchmarking outputs due to technical reasons (e.g. calculation engine failure, unavailable data feeds, rules engine malfunction etc.)','Number (Integer)','0',NULL,'MSME');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7882,961,'Theme 02','Innovation','AP05','Artificial Intelligence','KPI','Regular','05.01.04','(iv)','Assessment of repayment capacity and risk indicators','Bank should report the % of eligible cases where the deployed AI solution failed to complete repayment capacity assessment or risk-indicator assessment due to technical reasons (e.g. failed scoring, incomplete inference, unavailable input services )','Number (Integer)','0',NULL,'MSME');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7883,962,'Theme 02','Innovation','AP05','Artificial Intelligence','KPI','Regular','05.01.04','(v)','Identification and synthesis of missing, inconsistent, or high-risk information','Bank should report the % of eligible cases where the deployed AI solution failed to identify, flag, or synthesize missing, inconsistent, anomalous, or high-risk information due to technical reasons.','Number (Integer)','0',NULL,'MSME');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7884,963,'Theme 02','Innovation','AP05','Artificial Intelligence','KPI','Regular','05.01.04','(vi)','Generation of underwriting observations, commentary, and risk flags','Bank should report the % of eligible cases where the deployed AI solution failed to identify, flag, or synthesize missing, inconsistent, anomalous, or high-risk information due to technical reasons.','Number (Integer)','0',NULL,'MSME');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7781,860,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI/KPI','Regular','05.01.01 (A)','05.01.01','AI Project management office and lifecycle management capabilities',NULL,NULL,'As on 31st Mar 2026',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7782,861,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.01.01 (A)','(A)','Whether bank has developed a centralized AI project management office with the following  monitoring capabilities','including for timely visibility into the status, performance, adoption, and value realization of deployed AI use cases','Formula Count','0',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7783,862,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.01.01 (A)','(i)','Centrlaized digital dashboards to provide use case wise visibility across all lifecycle stages (e.g. pipeline, proof of concept, pilot / limited roll-out, and full-scale deployment)','To enable management to track the overall status and maturity of AI initiatives across the bank. For a pilot use case , bank to provide documentation for both pilot phase and POC Phase in the monitoring tool ;  Project charter for each use case and dicuementation for each phase of roll out of AI use cases;','Yes/No','No',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7784,863,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.01.01 (A)','(ii)','Stage wise documentation / record capture and storage for each use cases','Key documents and records to be systematically captured, updated, and stored for each AI use case at the relevant lifecycle stage, so that progress, approvals, and outcomes can be reviewed in a standardized and auditable manner.',NULL,NULL,NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7785,864,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.01.01 (A)','(a)','Project charter with use case objective','A documented project charter should be available for each AI use case, clearly capturing the business objective, problem statement, scope, intended users, ownership, and expected outcomes of the use case.','Yes/No','No',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7786,865,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.01.01 (A)','(b)','Documentation of key data inputs, sources, assumptions, and model development approach',NULL,'Yes/No','No',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7787,866,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.01.01 (A)','(c)','Model evaluation and validation report (UAT report, Go live document certified by competent authority)','Including testing results, user acceptance testing outcomes, validation findings, and the go-live approval / certification by the competent authority, as applicable.','Yes/No','No',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7788,867,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.01.01 (A)','(d)','Model deployment and operational plan (runbook)','With records on out how the AI solution will be deployed, monitored, operated, supported, and managed in production, including escalation and issue-handling processes where relevant.','Yes/No','No',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7789,868,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.01.01 (A)','(e)','Compliances checklist including inter deparmental approvals','Capturing required reviews and approvals across relevant departments','Yes/No','No',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7790,869,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.01.01 (A)','(f)','Defined  target state and outcomes','including the intended deployment scale, target operating model, expected adoption, and measurable business impact or performance improvements to be achieved.','Yes/No','No',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7791,870,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.01.01 (A)','(iii)','Regular review mechanisms led by the relevant departments led by top management','To monitor implementation progress, review value realization, prioritize investments, identify lagging use cases etc.','Yes/No','No',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7792,871,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.01.01 (A)','(iv)','Capbilities to move seamlessly from enterprise-wide AI portfolio view to business unit, function, individual use case, and KPI-level insights','Capability to enable both strategic oversight and detailed review of performance, deployment status, and issues.','Yes/No','No',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7793,872,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.01.01 (A)','(v)','Capture adoption and usage of deployed AI use cases across the bank','Dashboard to provide with visibility into scale of deployment, active usage, and coverage across relevant user groups or customer segments. Dashboards to report employee adoption for internal AI solutions and customer adoption for customer-facing AI solutions','Yes/No','No',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7794,873,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.01.01 (A)','(vi)','Capturing actual business impact achieved from identified deployed AI use cases and compare it against defined target outcomes','Bank to show documentation of methodology for capturing business impact for each use case and upload in dashboard  Illustrative list of business impact metrics include turnaround time reduction, productivity gains, customer query resolution, revenue uplift etc.','Yes/No','No',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7795,874,'Theme 02','Innovation','AP05','Artificial Intelligence',NULL,'Regular','05.01.01 (A)',NULL,NULL,NULL,NULL,NULL,NULL,'DIT');
