INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7801,880,'Theme 02','Innovation','AP05','Artificial Intelligence','KPI','Regular','05.01.01 (B)','Numerator','Of which, AI use cases reviewed / monitored through the centralized AI project monitoring tool','Banks to only report those use cases which have bene intergated into the centralized dashboard enabling review of implementation progress, deployment status, adoption, business impact, identifying risks /issues etc.','Number (Integer)','0',NULL,'DIT');
