INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7808,887,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI/KPI','Regular','05.01.02 (A)','(i)','AI use cases at the Proof of Concept stage as on end of reporting period','Include use cases residing in sandbox, development, or UAT / test environments only, and not yet deployed for live use by end users in production.','Appendix Linkage','13',NULL,'DIT/HR/Operations');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7809,888,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI/KPI','Regular','05.01.02 (A)','(ii)','AI use cases at limited roll out / pilot stage as on end of reporting period','Include use cases residing in a live production environment but restricted to a closed user group, limited customer set, selected branch / region, or controlled pilot population.','Appendix Linkage','5',NULL,'DIT/HR/Operations');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7810,889,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI/KPI','Regular','05.01.02 (A)','(iii)','AI use cases at full scale deployment stage as on end of reporting period','Include use cases residing in live production environments at intended business scale, available across the target user base, business scope, channel, or geography for which the solution was designed.','Appendix Linkage','2',NULL,'DIT/HR/Operations');
