INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7917,998,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.02.01','05.02.01','Core Tech Stack capabilities for Gen AI/Agentic AI implementation',NULL,NULL,'As on 31st Mar 2026',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7918,999,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.02.01',NULL,'Has the bank defined the set up approach for setting up the  following core elements  of the tech stack and infrastructure for GenAI/ Agentic AI implementation, in the context of their own defined scale of operations :-','For each of the core element mentioined below, bank''s maturity to be assessed across the four levels:   (i) Level 1 shall be marked where the approach for the relevant core element has been formally defined below  (ii) Level 2 where setup or implementation has been initiated;  (iii) Level 3 where setup has been initiated and is progressing on track in line with the approved roadmap, milestones, and timelines; and  (iv) Level 4 where setup has been completed and is considered adequate to meet the Bank’s requirements over the next 2–3 years.','Formula Count','0',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7919,1000,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.02.01','(i)','LLM licensing and model access approach defined','Bank to mark Y if it bank has assessed and defined how it will access GenAI / LLM models, including licensed proprietary models, open-source models, sovereign / government-backed models, or a multi-model approach, with clear principles for model selection, usage, and cost management.','Yes/No','no',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7920,1002,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.02.01','(iii)','On-premise / private cloud / private cloud / hybrid deployment model','Bank to mark Y if it has defined where GenAI models and workloads will be deployed, including on-premise, private cloud, hybrid, or segmented deployment based on use-case sensitivity, data residency, security, and performance requirements.','Yes/No','no',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7921,1003,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.02.01','(iv)','Model hosting and inference-serving approach','Bank to mark Y if it has defined how models will be hosted and served in practice, including inference endpoints, model-serving architecture, runtime environment, and separation of environments for development, testing, and production.','Yes/No','no',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7922,1004,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.02.01','(v)','Core GenAI stack components identified','Bank to mark Y if it has identified the minimum reusable stack components needed to implement GenAI use cases, such as  - model gateway / access layer,  - orchestration layer,  - prompt management,  - retrieval / vector database, -  API integration, and monitoring.','Yes/No','no',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7923,1005,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.02.01','(vi)','Security and compliance architecture for GenAI infrastructure','Bank to mark Y if it has defined the core controls required for GenAI infrastructure, including access control, encryption, audit logging, environment segregation, data protection, and safeguards for use of sensitive banking data.','Yes/No','no',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7924,1006,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.02.01','(vii)','Ownership and operating model for GenAI','Bank to mark Y if it has defined which teams will own, manage, and operate the GenAI stack and infrastructure across technology, cloud / infra, AI / data, security, and business functions.','Yes/No','no',NULL,'DIT');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7925,1007,'Theme 02','Innovation','AP05','Artificial Intelligence','KCI','Regular','05.02.01','(viii)','LLM vetting, third-party model governance, and approval methodology','Bank to mark Y if it has defined the methodology, governance process, and approval framework for independently evaluating and approving LLMs, GenAI models, and related implementation methodologies proposed by third-party vendors or partners, including criteria for model suitability, risk, compliance, security, and periodic re-validation.','Yes/No','no',NULL,'DIT');
