INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (7932,1014,'Theme 02','Innovation','AP05','Artificial Intelligence','KPI','Regular','05.02.02 (A)','(A)','Compute Infrastructure Readiness','Measures the extent to which the Bank has already acquired, or firmly committed to acquire, the GPU / accelerator capacity required under its approved AI / IT roadmap over the next three years. This is intended to assess forward readiness of compute infrastructure for planned GenAI, and Agentic AI use cases.','Formula (%)','0.62962962962962998',NULL,'DIT');
