INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8546,1641,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.04.01 (A)','(A)','Does the bank have a structured framework for identifying, deploying and monitoring self-service infrastructure (ATM, cash recyclers, passbook kiosks, etc.) in branches to enable migration of transactions from teller counters?','Mark “Yes” wherever applicable:','Formula Count','0','Operations','Operations');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8547,1642,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.04.01 (A)','(i)','A data-driven study has been conducted in the last 12 months to identify branches suitable for deployment of self-service infrastructure based on transaction volumes, customer profile and branch load','#The bank should have a documented study conducted within the last 12 months identifying branches suitable for deployment.   #The study should be based on quantitative data such as transaction volumes (cash vs non-cash), footfall, teller load, peak hour congestion, and customer profile (urban/rural, digital adoption levels).','Yes/No','no','Operations','Operations');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8548,1643,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.04.01 (A)','(ii)','Defined methodology exists for identification of branches (e.g., transaction mix analysis, peak load analysis, cost-benefit assessment, customer behavior patterns)','#The bank should have a standardized and documented methodology for selecting branches, including parameters such as transaction mix (cash vs digital), peak load analysis, cost-benefit assessment (CAPEX vs savings), and customer behavior patterns.','Yes/No','no','Operations','Operations');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8549,1644,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.04.01 (A)','(iii)','List of identified branches for deployment of ATMs, cash recyclers, passbook kiosks and other self-service infrastructure is maintained and tracked','#The bank should maintain a centralized list of branches identified for deployment, including type of infrastructure (ATM, recycler, kiosk), date of identification and status. This list should be system-maintained or available through MIS, and updated periodically.','Yes/No','no','Operations','Operations');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8550,1645,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.04.01 (A)','(iv)','Deployment progress is monitored against identified branches with defined timelines','#The bank should track actual deployment against the identified list, with clear timelines (planned vs actual).   #There should be a monitoring mechanism (e.g., dashboards/reports) showing progress, delays, and reasons for non-deployment, along with accountability for closure.','Yes/No','no','Operations','Operations');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8551,1646,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.04.01 (A)','(v)','Branch-level dashboards track migration of transactions from teller counters to self-service channels','#The bank should have dashboards that track the shift of transactions from teller counters to self-service channels (ATM/recycler/kiosk) at branch level. This should include measurable indicators such as: (a) Share of transactions migrated (b) Trends analysis QoQ','Yes/No','no','Operations','Operations');
