INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8419,1513,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.01.01 (E)','(i)','Partner-wise visibility of leads generated, applications, approvals and disbursements','#The dashboard should provide end-to-end funnel visibility for each partner, tracking movement from lead generation to application, approval and final disbursement.  #The dashboard should be available to relevant stakeholders across levels, including top management (CXOs), business heads, partnership/alliances teams, product teams, regional/zonal heads, etc. with role-based access to ensure appropriate visibility and actionability at each level.','Yes/No','no',NULL,'ECOSYSTEM/DBV');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8420,1514,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.01.01 (E)','(ii)','Product-wise performance tracking is available (loans, deposits, fee-based products) for each partner',NULL,'Yes/No','no',NULL,'ECOSYSTEM/DBV');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8421,1515,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.01.01 (E)','(iii)','Revenue / business contribution (loan disbursement, deposits mobilized, fee income) is tracked partner-wise','#The dashboard should capture the actual business value generated from each partner, including loan volumes, deposit balances and fee income, to assess contribution and prioritize partnerships.','Yes/No','no',NULL,'ECOSYSTEM/DBV');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8422,1516,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.01.01 (E)','(iv)','Portfolio quality metrics (e.g., early delinquency, 30+ DPD) are monitored for partner-wise sourced business',NULL,'Yes/No','no',NULL,'ECOSYSTEM/DBV');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8423,1517,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.01.01 (E)','(v)','SLA / turnaround time tracking is available for partner-sourced applications','#The dashboard should monitor processing timelines (e.g., application to approval/disbursement) for each partner to identify delays and take corrective actions','Yes/No','no',NULL,'ECOSYSTEM/DBV');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8424,1518,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.01.01 (E)','(vi)','Dashboard supports multi-level drill-down','Users should be able to drill down from aggregate performance to granular levels covering the following: (a) Partner  (b) Product  (c) Area/Branch/ ZO (d) Customer segment','Yes/No','no',NULL,'ECOSYSTEM/DBV');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8425,1519,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.01.01 (E)','(vii)','Periodic review mechanism is in place with defined action tracking for underperforming partnerships','#A structured review process (e.g., monthly/quarterly) where underperforming partners are identified, corrective actions are defined, tracked and monitored for closure.','Yes/No','no',NULL,'ECOSYSTEM/DBV');
