INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8441,1535,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.01.02 (B)','(ii)','Target segment is defined (e.g. customers active on MB but not using bank’s UPI)','#The bank should clearly define a targetable segment such as: -Customers registered on mobile banking but not registered on bank’s UPI -Customers registered on bank’s UPI but inactive -Customers actively using UPI via other PSPs  #Segmentation logic should be documented and system-driven.','Yes/No','no','Digitization','Digitization');
