INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8464,1559,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.02.01 (A)','(i)','Customer-level propensity models are built (not only segment-based rules)','#The bank should use data-driven models at an individual customer level (based on transaction behaviour, balances, demographics, etc.) to predict likelihood of product uptake, rather than relying only on broad segment rules','Yes/No','NO',NULL,'Strategy-ACoE/DBV');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8465,1560,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.02.01 (A)','(ii)','Multi-product prioritization logic is available','#The system should be able to identify and rank multiple product offers for a customer (e.g., loan, deposit, card, investment) and prioritize the most relevant offer based on defined logic such as propensity, profitability or customer need.','Yes/No','NO',NULL,'Strategy-ACoE/DBV');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8466,1561,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.02.01 (A)','(iii)','NBA engine is integrated with mobile banking, internet banking, CBS, CRM systems and front-line interfaces for employees and call centers','#The capability should include system-driven alerts or notifications in CBS identifying customers with high potential, and RM dashboards providing model-driven customer insights to enable proactive engagement and targeted outreach','Yes/No','NO',NULL,'Strategy-ACoE/DBV');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8467,1562,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.02.01 (A)','(iv)','Dedicated dashboard exists to monitor model performance, offer acceptance rate and conversion uplift','#Dashboard should track key metrics such as number of offers served, acceptance rate, conversion rate and uplift vs control, enabling monitoring of effectiveness of personalization models','Yes/No','NO',NULL,'Strategy-ACoE/DBV');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8468,1563,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.02.01 (A)','(v)','Formal governance framework is established for model approval, periodic review and bias monitoring',NULL,'Yes/No','NO',NULL,'Strategy-ACoE/DBV');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8469,1564,'Theme 02','Innovation','AP07','Re-imagined Business Models','KCI','Regular','07.02.01 (A)','(vi)','Customer feedback on relevance and suitability of offers is captured and incorporated into the NBA engine for continuous improvement','#The bank should capture customer feedback on offers (e.g., accepted, rejected, ignored, reasons where available) through digital channels, RM interactions or campaign responses, and use this feedback to refine model parameters, improve targeting accuracy and enhance relevance of future recommendations','Yes/No','NO',NULL,'Strategy-ACoE/DBV');
