INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8839,1938,'Theme 03','Socio-economic Impact','AP09','Inclusive Banking','KCI','Regular','09.01.01 (A)','(A)','Accessibility Cell for enhancing Divyangjan-focused accessibility','There have been  representation from Divyangjan stipulated for customer grievance redressal, digital accessibility enablement, and customer service committee. This edition aims to build on the established capability setup to streamline focus towards accessibility for Divyangjan via centralised and dedicated efforts via an Accessibility Cell. The Accessibility Cell could be a part of the Customer Experience (CX) CoE.','Formula summation','7',NULL,'DIT-Union Access');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8840,1939,'Theme 03','Socio-economic Impact','AP09','Inclusive Banking','KCI','Regular','09.01.01 (A)','(i)','Defined Accessibility Cell/team structure and reporting mechanism','Illustrative team structure below, banks may explore team size and structures individually  - An officer of DGM/AGM to lead the cell - A project manager - At least 2 Divyangjan employees driving initiatives across physical and digital infrastructure, product/journey testing. Divyangjan team members to also be part of CX Cell. Team size and composition could vary across banks basis individual needs',NULL,'4',NULL,'DIT-Union Access');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8841,1940,'Theme 03','Socio-economic Impact','AP09','Inclusive Banking','KCI','Regular','09.01.01 (A)','(a)','Team size and role requirements','Team to be at least a 4 members team including a DGM/AGM to lead and 2 Divyangjan members','Yes/No','Yes',NULL,'DIT-Union Access');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8842,1941,'Theme 03','Socio-economic Impact','AP09','Inclusive Banking','KCI','Regular','09.01.01 (A)','(b)','Job descriptions for all team members','Scope of work including driving key identified initiatives by accessibility cell to be detailed.','Yes/No','Yes',NULL,'DIT-Union Access');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8843,1942,'Theme 03','Socio-economic Impact','AP09','Inclusive Banking','KCI','Regular','09.01.01 (A)','(c)','Representation of Divyangjans','At least 2 Divyangjan employees driving initiatives across physical and digital infrastructure','Yes/No','Yes',NULL,'DIT-Union Access');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8844,1943,'Theme 03','Socio-economic Impact','AP09','Inclusive Banking','KCI','Regular','09.01.01 (A)','(d)','Defined criteria for selection of key personnel detailing required knowledge, or any other specifications as necessary','Required knowledge on accessibility related topics e.g., assisted technology know-how, IAAP certified auditor, etc. Selection criteria to be fulfilled either before taking up the role or stipulated mandatory trainings to be completed within 30 days of assuming charge','Yes/No','Yes',NULL,'DIT-Union Access');
