INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8893,1992,'Theme 03','Socio-economic Impact','AP09','Inclusive Banking','KCI','Regular','09.01.01 (E)','(i)','Branches, self-service touchpoints,  ATM / e-lobby / digital hubs etc.','Dashboard to capture information mentioned in annexture 09.01.02 (A) along with following: - Photos of physical branch infra and  - Targets and achievement % at bank / zone/ region level to increase the count of branches with enahnced accessibility features,  - Target and achievement % of self-service touchpoints with accessibility features within bank defined timelines','Yes/No','Yes',NULL,'DIT-Union Access');
