INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (8895,1994,'Theme 03','Socio-economic Impact','AP09','Inclusive Banking','KCI','Regular','09.01.01 (E)','(iii)','Progress of accessibility certification for Digital channels (employee facing) and tracking pending action items','Employee-facing systems such as HR portal, LMS, attendance / leave system, internal communication portals, and productivity tools; Either of below certifications to be provided for applicable employee-facing systems  - IS17802 / WCAG 2.1 - WCAG 2.2 Action items for enhancing effectiveness of key journeys to also be tracked','Yes/No','Yes',NULL,'DIT-Union Access');
