INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9160,2280,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.02.01 (A)','10.02.01','Incentivize borrower decarbonization',NULL,NULL,'As on 31st Mar 2026',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9161,2281,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.02.01 (A)',NULL,'Transition Finance pathway','Metric to be information only and revisited once clarity emerges basis policy / directions from Indian regulatory bodies / government authorities',NULL,NULL,NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9162,2282,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.02.01 (A)','(A)','Does the Bank has a documented transition finance policy/framework (Board approved), including:','This metric checks whether the bank has defined the overall transition-finance framework at bank level. It tests the common bank-level policy elements such as what can qualify as transition finance, what product structures may be used, how eligibility is assessed, what transition outcomes are to be monitored, what governance / review applies, and what data / evidence will be used.','Formula Count','0',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9163,2283,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.02.01 (A)','(i)','Eligibility/definition for transition finance borrowers, project characteristics, and eligible transition activities','Bank may refer to Index of Eight Core Industries as specified by Department for Promotion of Industry and Internal Trade, Ministry of Commerce. Specified sectors include - coal, crude oil, natural gas, refinery products, fertilizers, steel, cement, and electricity Eligibility / definition for transition finance defined, including eligible transition activities, eligible borrower / project characteristics, and alignment of such definition to a recognized external transition-finance framework / guidance adopted by the bank. Banks may refer these frameworks to define eligible transition finance activities as below: - Net-Zero Banking Alliance (NZBA) Transition Finance Guide - ICMA Climate Transition Finance Handbook (CTFH) - GFANZ transition-plan framework / guidance','Yes/No','No',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9164,2284,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.02.01 (A)','(ii)','Defined product templates / SOPs / playbooks','Specifies the transition finance product structure(s) / template(s), key product features, eligible end-use / transition purpose, and standardized SOP / templates to be used for origination, appraisal, documentation, sanction, and monitoring, as applicable. Transition outcomes for financed activity under the framework to be mutually agreed upon by bank and borrower for periodic review Illustrative examples for products that can be designed under transition finance framework include (not enhaustive): 1. Use-of-proceeds based funding i.e., loans to eligible borrower for specific transition based activities such as loans for captive solar plants;  2. General corporate term loans with mutually agreed transition KPIs such as reduction in GHG emissions over a mutually agreed time frame by bank and borrower','Yes/No','No',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9165,2285,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.02.01 (A)','(iii)','Assessment approach','Assessment approach defined for evaluating and documenting transition-finance eligibility at appraisal / sanction stage, including treatment of fully eligible and partially eligible transactions, eligibility threshold where applicable, and approach for counting only the eligible portion of financing','Yes/No','No',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9166,2286,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.02.01 (A)','(iv)','Monitoring expectations for transition outcomes','Monitoring expectations: Specifies what transition outcomes / milestones / indicators are tracked post-sanction and how often they are tracked','Yes/No','No',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9167,2288,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.02.01 (A)','(vi)','Approach for data/evidence and disclosures used for assessment/monitoring','Data/evidence approach: Specifies the data and borrower evidence used for assessment and monitoring, and methodology to capture the same','Yes/No','No',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9168,2289,'Theme 03','Socio-economic Impact','AP10','Sustainability',NULL,'Regular','10.02.01 (A)',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
