INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9180,2301,'Theme 03','Socio-economic Impact','AP10','Sustainability','KPI','Regular','10.02.01 (C)','Denominator','Total value of corporate advance portfolio in hard-to-abate sectors (INR Cr) at end of reporting period','Sum of corporate advance portfolio across all 8 hard-to-abate sectors as per denominator in annexure','Appendix Linkage','0',NULL,'RMD-ESG');
