INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9187,2308,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.02.02 (A)','10.02.02','Green finance framework, deployment, and capital raising',NULL,NULL,'As on 31st Mar 2026',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9188,2309,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.02.02 (A)','(A)','Does the bank have a Board-approved green finance taxonomy / framework aligned with RBI’s Directions on Climate Finance and Management of Climate Change Risks, 2025 refreshed in the last 12 months from the end of reporting quarter?','Board-approved framework defining eligible green-finance categories, classification basis, exclusions, and how transactions will be tagged as green. RBI’s Directions on Climate Finance and Management of Climate Change Risks require banks to put in place a Board-approved framework for green finance / climate finance.','Formula Count','4',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9189,2310,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.02.02 (A)','(i)','Green Finance Framework defining eligible assets, use of proceeds, governance, and reporting approach','Define the external / investor-facing framework for green capital raising, including eligible asset categories, basis for classification, intended use of proceeds, governance structure, and broad reporting commitments applicable to the instrument.','Yes/No','Yes',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9190,2311,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.02.02 (A)','(ii)','Process to identify, confirm eligibility of, and ring-fence the pool of green loans / projects to back such issuance','Define the internal process for identifying the pool of green loans / projects proposed to support the issuance, confirming their eligibility under the framework, and designating such pool for assigning and tracking allocation of proceeds against eligible assets.','Yes/No','Yes',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9191,2312,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.02.02 (A)','(iii)','Internal tracking mechanism for allocation, monitoring, and reporting of proceeds','Define the internal mechanism for tracking allocation of proceeds to the eligible pool, monitoring unallocated proceeds, and maintaining records required for internal review and external reporting.','Yes/No','Yes',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9192,2313,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.02.02 (A)','(iv)','Approach for issuance and post-issuance impact reporting','Define the approach for execution of the issuance and post-issuance reporting to investors, including allocation reporting and impact reporting for the eligible assets / projects financed through such instrument. Impact report to be externally reviewed and presented to Board quarterly.','Yes/No','Yes',NULL,'RMD-ESG');
