INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9097,2212,'Theme 03','Socio-economic Impact','AP10','Sustainability','KPI','Regular','10.01.01 (B)','(B)','Share (%) of bank-owned premises covered under Building Management Systems with ESG monitoring / tracking ESG outcomes on building utilities','#Building Management Systems (BMS) integrate smart sensors, software, and network connectivity to monitor, control, and optimize building operations such as energy usage, HVAC systems, lighting, and security in real-time through data-driven automation. e.g., # 1. Water conservation practices a. Install low-flow faucets, toilets, and sensor-activated taps to significantly reduce water usage in washrooms and kitchens b. Deploy leak detection sensors and smart water meters to quickly identify and address leaks, preventing water wastage b. Implement rainwater harvesting systems to collect and reuse rainwater for landscaping and non-potable purposes 2. Energy efficiency practices a. Upgrade to LED lighting and install motion or occupancy sensors to ensure lights are only used when needed b. Optimize HVAC systems with BMS for automated temperature control, zoning, and scheduling based on occupancy and weather conditions c. Implement real-time energy monitoring and analytics through BMS to identify inefficiencies and track energy consumption trends d. Improve building insulation and use energy-efficient windows to reduce heating and cooling loads 3. Waste segregation a. Provide color-coded bins and clear signage to enable easy segregation of wet, dry, and hazardous waste at the source b. Set up partnerships with authorized recyclers and composting agencies to ensure segregated waste is properly processed and diverted from landfills','Formula(%)','0.2',NULL,'SSD');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9098,2214,'Theme 03','Socio-economic Impact','AP10','Sustainability','KPI','Regular','10.01.01 (B)','Numerator','Of which, total number of bank-owned premises covered under Building Management Systems with ESG monitoring / tracking ESG outcomes on building utilities at the end of the reporting quarter','Refer to annexure 10.01.01','Appendix Linkage','1',NULL,'SSD');
