INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9118,2236,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.01.02 (A)','(iii)','Policy for arranging setup of EV charging infrastructure through approved / eligible vendor or reimbursement/partial reimbursement, at bank''s own residential premises (e.g., bank quarters) for individual parking spots','These are charging infrastructure to be placed in individual parking areas. Reimbursement could be considered for parts of the infrastructure that could be reused by the next residents','Yes/No','No',NULL,'SSD');
