INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9350,2472,'Theme 03','Socio-economic Impact','AP11','Empowering emerging segments','KCI','Regular','11.01.01 (D)','(i)','Central sunrise sector team','Team members responsible for sales / origination, appraisal, monitoring, risk, and techno-economic support for large-ticket cases (ticket size above INR 25 Cr.), and for branch support on mid-ticket cases (ticket size between 10 Cr. To 25 Cr.)','Yes/No','Yes',NULL,'LCV');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9351,2473,'Theme 03','Socio-economic Impact','AP11','Empowering emerging segments','KCI','Regular','11.01.01 (D)','(ii)','Sunrise sector trained field officers at relevant MSME / business branches','Personnel trained in sunrise sectors relevant to their mapped clusters / geographies. Bank to ensure documented geographical sector mapping for field-level officers. Mapping identifies relevant circles / clusters, the sunrise sectors most relevant in those areas, and the key ecosystem participants operating there; and uses this mapping to determine field coverage responsibilities and sector-specific training needs','Yes/No','Yes',NULL,'LCV');
