INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9242,2363,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.03.01',NULL,'Climate risk governance',NULL,NULL,NULL,NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9243,2364,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.03.01',NULL,'Does the bank have a Board-approved climate-risk governance framework for both physical risk and transition risk (refreshed at least once in the last 12 months) covering atleast the following:','Climate-risk governance framework to be Board-approved, with refresh at least once in the last 12 months, approved by competent authority not below the rank of ED. Building on earlier EASE initiative, the refresh is expected to keep the framework aligned with recent regulatory and market developments, including RBI’s 2025 Directions on Climate Finance and Management of Climate Change Risks, RBI’s ongoing climate-risk assessment / data initiatives, the Government of India’s draft Climate Finance Taxonomy, and evolving climate commitments / disclosure expectations linked to India’s NDCs.','Formula Count','3',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9244,2365,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.03.01','(i)','Governance roles and ownership defined for climate-risk management, including Board / top-management oversight and identified management owners',NULL,'Yes/No','Yes',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9245,2366,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.03.01','(ii)','Climate-risk framework covering both physical risk and transition risk and identified in-scope portfolio segments','In-scope segments across retail, agri, MSME, corproate loans to be taken up customer segment-wise, geography-wise, loan threshold-wise.','Yes/No','Yes',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9246,2367,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.03.01','(iii)','Phase-wise roadmap to include climate risk assessment in underwriting across loan portfolio segments','Banks are expected to have a roadmap to gradually expand list of loan portfolio segments in scope for climate risk assessment during underwriting and subsequent monitoring','Yes/No','No',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9247,2368,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.03.01','(iv)','Board-approved climate-risk targets / coverage aspirations defined for the reporting period or target period','May include targets / aspirations relating to physical and transition risk assessment coverage, climate-risk stress testing, or other bank-defined climate-risk measures. Illustrative metrics for target setting (non-exhaustive):  - Share of portfolio in vulnerable geographies,  - Share of secured assets in identified high-risk geographies with valid insurance coverage, climate-risk training coverage','Yes/No','No',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9248,2369,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.03.01','(v)','Climate-risk review cadence and action-tracking mechanism defined for governance review of key climate-risk themes, concentrations, and improvement actions',NULL,'Yes/No','No',NULL,'RMD-ESG');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9249,2370,'Theme 03','Socio-economic Impact','AP10','Sustainability','KCI','Regular','10.03.01','(vi)','External climate-risk disclosure approach defined, including named disclosure channel for publication of climate-risk disclosures during the reporting year','This may include IFRS S2 / TCFD-aligned disclosure or regulatory-mandated equivalent, where applicable','Yes/No','Yes',NULL,'RMD-ESG');
