INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9370,2492,'Theme 03','Socio-economic Impact','AP11','Empowering emerging segments','KCI','Regular','11.01.01 (F)','(ii)','Defined curriculum topics and training modules exist for sunrise sectors, covering internal modules, external / industry sessions, assessment or quiz mechanism, and LMS-based completion tracking for ≥4 sunrise sectors','Level 2 (Including requirements stipulated for reaching maturity level 1)- Role-based curriculum is defined for personnel mapped to origination / appraisal / risk / monitoring roles, with minimum training hours specified for each role','Yes/No','no',NULL,'LCV');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9371,2493,'Theme 03','Socio-economic Impact','AP11','Empowering emerging segments','KCI','Regular','11.01.01 (F)','(iii)','Defined curriculum topics and training modules exist for sunrise sectors, covering internal modules, external / industry sessions, assessment or quiz mechanism, and LMS-based completion tracking for ≥6 sunrise sectors','Level 3 (Including requirements stipulated for reaching maturity level 2);  Additionally, following are included;  1) external faculty / industry sessions 2) Sector modules are co-developed with leading institutes;  3) Assessment / quiz mechanism is in place;  4) Module training completion is tracked in LMS','Yes/No','no',NULL,'LCV');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9372,2494,'Theme 03','Socio-economic Impact','AP11','Empowering emerging segments','KCI','Regular','11.01.01 (F)','(iv)','Certification pathway defined and operationalized to develop relevant sunrise sector knowledge and skill capabilities for central team (for ≥6 sunrise sectors)','Level 4 (Including requirements stipulated for reaching maturity level 3)Certification is linked to role eligibility for sunrise sector underwriting / risk sign-offs, as per bank policy; Illustrative certifications (non-exhaustive): Listed as indicative examples only; banks may choose equivalent programmes as per role and internal policy: - IFRS Foundation FSA Credential: Fundamentals of Sustainability Accounting by International Financial Reporting Standards.IFRS Foundation, covers how sustainability information links to financial performance and decision-useful disclosures - GARP Financial Risk Manager (FRM®) Certification: Financial risk management concepts applicable to credit/market/liquidity risk. - ASCM CSCP: Certified Supply Chain Professional by Association for Supply Chain Management, covers supply-chain know-how relevant for manufacturing-linked sunrise sectors and working-capital cycles','Yes/No','no',NULL,'LCV');
