INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9665,3206,'Theme 04','Excellence','AP14','Customer Experience Transformation','KCI','Regular','14.01.02 (B)','(v)','List of rewards and recognitions awarded across top-performing cohort during the quarter','# Recognition to cover top-performing branches or employees among a cohort (e.g., top 10%)  # Cohorts could be defined basis: (a) Branch size, (b) Region (Zone, circle, area, etc.), (c) Segment (MSME branhces, Retail branches, etc.)','Yes/No','no',NULL,'Operations-CSEC');
