INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9616,3154,'Theme 04','Excellence','AP14','Customer Experience Transformation','KCI','Regular','14.01.01 (A)','(A)','Has the bank institutionalized an empowered CX team/cell as a central governance and orchestration layer to drive cross-functional CX improvements?','# CX cell/ team is a central governance layer distinct from Customer Service (execution) and Grievance teams  # It focuses on standardization, cross-functional coordination, and tracking resolution of systemic CX issues','Formula Count','4',NULL,'Operations-CSEC');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9617,3155,'Theme 04','Excellence','AP14','Customer Experience Transformation','KCI','Regular','14.01.01 (A)','(i)','Headed by not below DGM/GM level','# preferably reporting to CGM or above','Yes/No','YES',NULL,'Operations-CSEC');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9618,3156,'Theme 04','Excellence','AP14','Customer Experience Transformation','KCI','Regular','14.01.01 (A)','(ii)','Defined roles','# The following roles may constitute a dedicated CX team: i) To oversee journey design efforts, pain points, cross-functional collaboration  ii) To provide oversight of CX initiatives, journey metrics etc iii) To performs data analysis and reporting to support CX initiatives iv) To create and implement surveys to gather customer feedback and insights  #  >50% KRA of the employees should be mapped with the customer experience transformation # All the above capabilities are separate from Grievances/Complaint Redressal and customer service Cell','Yes/No','YES',NULL,'Operations-CSEC');
