INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9626,3164,'Theme 04','Excellence','AP14','Customer Experience Transformation','KCI','Regular','14.01.01 (B)','(i)','Reporting and quarterly review cadence for the CX cell with the Board sub-committee',NULL,'Yes/No','YES',NULL,'Operations-CSEC');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9627,3166,'Theme 04','Excellence','AP14','Customer Experience Transformation','KCI','Regular','14.01.01 (B)','(iii)','Tracking CX performance across branch/ service levels (KPIs)','# CX performance may be tracked using: (a )Service-level CSAT (mapped to branch/service) (b) Complaint metrics (FTR, TAT)  # Branches may be evaluated using CX scorecards or dashboards comprising avg. CSAT score of various products and services availed at the branch during the reporing period','Yes/No','no',NULL,'Operations-CSEC');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9628,3167,'Theme 04','Excellence','AP14','Customer Experience Transformation','KCI','Regular','14.01.01 (B)','(iv)','Independent analysis of customer feedback and survey output analysis to identify root causes and forward-looking insights and action items, with well-defined governance for reviews by the competent authority.','# CX cell to have a unified report with synthesized findings across customer feedback, customer survey analysis, with forward-looking segment specific insights e.g., from HNIs, Senior citizens, insights from Divyang-jan cell. # Executive reports with recommendation with root cause analysis and structural drivers for Board-sub committiee. Report to include time-bound corrective action framework: -Categorized into short-term, medium-term, and long-term fixes/ action items -For each action: Specific intervention defined, Owner department fixed, Timeline defined, Accountability documented # There should be a consolidated view from the single report, platform or dashboard (instead of multiple) # Feedback reports, survey reports with date range facility','Yes/No','no',NULL,'Operations-CSEC');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9629,3168,'Theme 04','Excellence','AP14','Customer Experience Transformation','KCI','Regular','14.01.01 (B)','(v)','Conduct independent studies/surveys from time to time (as stipulated by the competent authority/Board sub-committee) for enhancing CX','# e.g. Study the impact of delegation of financial powers for approving certain benefits, refunds of fees/charges, which may serve as inputs during the periodic reviews of the policy for delegation of financial powers (as may be stipulated based on findings of such studies/surveys). Study on identifying branches with chronic connectivity issues, customer service issues, and recommending potential corrective measures and monitoring impact over time.  #Banks may explore automated tools for generating reports for chronic/ low CX branches  #Study/ survey to be conducted at least once per quarter on atleast one identified opportunity for CX experience via Digital channels (SMS, email, app-based, etc), Tele-calling , etc.','Yes/No','YES',NULL,'Operations-CSEC');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9630,3170,'Theme 04','Excellence','AP14','Customer Experience Transformation','KCI','Regular','14.01.01 (B)','(vii)','Organization-wide employee engagement through leadership communication on CX sensitization and CX culture building initiative','# e.g., Way we work rituals led by CX champions','Yes/No','NO',NULL,'Operations-CSEC');
