INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9742,3284,'Theme 04','Excellence','AP14','Customer Experience Transformation','KCI','Regular','14.01.06',NULL,'Has the bank conducted a structured review from CX point of view in the current FY to assess and define where Delegation of Powers (DoP) is required for improving CX outcomes covering?',NULL,'Formula Count','0',NULL,'Operations-CSEC');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9743,3285,'Theme 04','Excellence','AP14','Customer Experience Transformation','KCI','Regular','14.01.06','(i)','Evaluation of potential monetary / non-monetary powers that could be delegated to branch managers, officers, call center staff, etc., to enable faster CX resolution','# Assessment to identify: (a) Specific use cases (e.g., fee reversal, service recovery gestures, complaint closure decisions) (b) Role-wise delegation possibilities (c) Benchmarking with peer banks and industry practices to identify opportunities and best practices (d) Customer feedback/ reviews','Yes/No','no',NULL,'Operations-CSEC');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9744,3286,'Theme 04','Excellence','AP14','Customer Experience Transformation','KCI','Regular','14.01.06','(ii)','Assessment of how delegated powers could be linked to CX impact,  risk considerations, etc.','# Assessment to define: (a) Expected CX improvement (e.g., faster TAT, higher FTR, improved CSAT) (b) Risk considerations (misuse, financial exposure, compliance risks) (c) Segment-wise applicability, including: -Customer segments (e.g., HNI, senior citizens, priority customers, mass segment) -Differentiated delegation use cases across segments','Yes/No','no',NULL,'Operations-CSEC');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9745,3287,'Theme 04','Excellence','AP14','Customer Experience Transformation','KCI','Regular','14.01.06','(iii)','Evaluation of mechanisms needed to monitor usage patterns and manage risk through defined thresholds','# Evaluation to define: (a) Monitoring approach (reports / dashboards / alerts) (b) Thresholds for usage (limits, frequency, escalation triggers) -First-time usage (approval / validation / control mechanism) -Repeat usage (frequency caps, limits, exception handling, escalation triggers)','Yes/No','no',NULL,'Operations-CSEC');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9746,3288,'Theme 04','Excellence','AP14','Customer Experience Transformation','KCI','Regular','14.01.06','(iv)','Documentation of recommendations, proposed pilot/rollout plan, and accountable owner departments (where applicable)','# Study reports to include clearly documented recommendations and implementation approach: (a) Detailed findings with identified problem statements and improvement opportunities (b) Prioritized recommendations with expected impact on CX  # Proposed pilot / rollout plan (if any): (a) Defined pilot scope (where applicable) with timelines (b) Phased rollout plan (pilot → scale-up) (c) Success criteria / outcome metrics for evaluation  # Accountability and ownership (if any): (a) Owner department clearly identified for each recommendation (b) Timeline defined for implementation','Yes/No','no',NULL,'Operations-CSEC');
