INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9752,3294,'Theme 04','Excellence','AP14','Customer Experience Transformation','KPI','Regular','14.02.01 (A)','14.02.01','CX-to-Business impact linkage',NULL,NULL,'From 1st Jan 2026 to 31st Mar 2026',NULL,'Operations-CSEC');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9753,3295,'Theme 04','Excellence','AP14','Customer Experience Transformation','KPI','Regular','14.02.01 (A)','(A)','Bank-wide Net Promoter Score for the reporting quarter','# Time period - For baseline - 01.04.2025 - 31.03.2026, For Q1 - 01.04.2026 to 30.06.2026, For Q2- 01.04.2026 to 30.09.2026, For Q3 - 01.04.2026 to 31.12.2026, For Q4 - 01.04.2026 to 31.03.2027  # Methodology - NPS is calculated by asking customers a single question: On a scale of 0 to 10, How likely are you to recommend bank to a friend or colleague?  # For the purpose of this metric, Bank to exclude response from bank''s own employees, banks may track NPS from own employees separately.  # The scale is rated from 0 to 10. Depending on the responses, customers fall into one of 3 categories: 1. Promoters (Extremely likely to recommend) are customers who respond with a score of 9 or 10 2. Passives are customers who respond with a score of 7 or 8 3. Detractors (Not at all likely to recommend) are customers who respond with a score of 0 to 6   # Net Promoter Score (NPS%) = Total % of promoters – Total % of detractors','Formula (Avg)','92.76',NULL,'Operations-CSEC');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9754,3296,'Theme 04','Excellence','AP14','Customer Experience Transformation','KPI','Regular','14.02.01 (A)','(i)','Bank level Net Promoter Score (NPS) captured through branches','# NPS calculated based on responses collected from branch interactions.  # Includes responses collected through branch walk-in customers, Assisted onboarding / servicing, Branch-triggered surveys (QR / SMS / assisted feedback) with suitable cooling off period, etc.  # Consider setting the survey fill rate target at least 5 times the number of branches of the bank every quarter, for example, if the bank has 100 branches, the target for the quarter ending June 30th would be 500 completed survey responses. Similarly, for the subsequent quarter ending September 30th, a fresh set of 500 responses should be collected. Banks should endeavor to engage different respondents each quarter to capture a diverse range of customer feedback','Number','92.76',NULL,'Operations-CSEC');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9755,3297,'Theme 04','Excellence','AP14','Customer Experience Transformation','KPI','Regular','14.02.01 (A)','(ii)','Bank level Net Promoter Score (NPS) captured through digital channels','# NPS calculated based on responses collected from digital interactions. Channels to be covered: IB, MB, Website and portals, WhatsApp and Chatbots, Other digital self-service platforms  # Fill rate target for digital channels to be at least 2 times the number of branches of the bank every quarter','Number','92.76',NULL,'Operations-CSEC');
