INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9964,3844,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KCI','Regular','16.02.02 (B)','ii','Common digital NRI account opening journey with swimlanes for handling both cases where the NRI customer is situated overseas or in India','# Application form is available for digital completion and submission. Application form may include details around (but not limited to) preferred products and services (NRE/NRO, internet banking, cards, chequebook), tax, nominees, and other additional details beyond basic customer contact and email. # Design a journey that ensures: - If a customer is overseas at the time of application initiation, they are prompted to send documents directly to the central processing center or preferred home branch. - If an NRI customer is in India during digital application initiation, they can choose to visit their preferred home branch for document verification and submission or directly send documents to the CPC.','Yes/No','NO',NULL,'DMD');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9965,3845,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KCI','Regular','16.02.02 (B)','iii','Resumption of application journey and drop-off handling','# Journey allows customers to resume the application from the last saved stage.','Yes/No','NO',NULL,'DMD');
