INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9967,3847,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KCI','Regular','16.02.02 (B)','v','Communication of document requirements and next steps post application submission','# Post submission, the journey communicates required documents and next steps via on-screen prompts and notifications (email/SMS).','Yes/No','NO',NULL,'DMD');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9968,3848,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KCI','Regular','16.02.02 (B)','vi','Display of assigned processing centre or preferred home branch for document submission','# Customer is informed of the assigned processing centre / chosen preferred branch where documents are to be submitted.  # The processing centre may be system routed based on the preferred branch mapping or may be given as an option for the customer to select from (in case of multiple processing centres or customer situated in India at the time of application initiation).','Yes/No','NO',NULL,'DMD');
