INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9905,3784,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KPI','Regular','16.01.03 (A)','(A)','Acceptable stability in variance in Net Stable Funding Ratio (NSFR) observed with respect to Forecasted vs Actual, in the reporting quarter','# Acceptable Stability means variance should be within a - 5% to +10% range as a prudent practice','Formula','Yes',NULL,'RMD');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9906,3785,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KPI','Regular','16.01.03 (A)',NULL,'Difference between actual and forecasted NSFR','# If difference is within -5 to +10% w.r.t. actual and forecasted NSFR, then Accetable stability is Yes, otherwise No','Formula Difference','-0.02',NULL,'RMD');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9907,3786,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KPI','Regular','16.01.03 (A)','(i)','Actual NSFR reported at the end of reporting quarter','# Value is to be from the report directly generated from NSFR tool/portal and submitted to regulator','Number (%)','1.1599999999999999',NULL,'RMD');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9908,3787,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KPI','Regular','16.01.03 (A)','(ii)','Forecasted NSFR for the reporting quarter','# In case there is no forecasted NSFR (%), the denominator shall be regarded as Nil/Score will be 0, as it depicts no demonstration of forecasting capability.  # Forecasts should be done on quarterly basis for forward looking quarters.  # One figure for the entire year/ RBI prescribed minimum/target figure not to be considered, it is rather a projected figure for each quarters.','Number (%)','1.18',NULL,'RMD');
