INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9943,3822,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KCI','Regular','16.02.01 (C)','(i)','Business case including target geographies, clients and initial product/service scope','# Specifies target geographies and client segments (e.g., global corporates, NRIs, FIs and any others) and a realistic and phased product or service scope aligned to regulatory, operational and booking/ops readiness. Demonstrates clear prioritization and sequencing','Yes/No','no',NULL,'DFB/IBD');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9944,3823,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KCI','Regular','16.02.01 (C)','(ii)','Key risks, regulatory pathway, approvals and submission status (IFSCA and other approvals as applicable)','# Defines list of required approvals / licenses (IFSCA, RBI, etc.), with related risks specific to GIFT IFSC operations (for e.g., AML/sanctions requirements, cross-border regulatory compliance, and other risks), current stage (planned / submitted / approved with actual or projected timelines), and evidence of submission or regulator interaction.','Yes/No','no',NULL,'DFB/IBD');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9945,3824,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KCI','Regular','16.02.01 (C)','(iii)','Processes - Cross-border business operating model / SOP for GIFT IFSC','# The operating model / SOP includes sourcing and onboarding, transaction processing, approving and servicing of cross border business through GIFT IFSC.','Yes/No','no',NULL,'DFB/IBD');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9946,3825,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KCI','Regular','16.02.01 (C)','(iv)','People - Specialised talent model (roles + skills) for GIFT IFSC execution','# “Specialised” refers to cross-border product/regulatory execution roles (not generic branch roles). Plan should define key roles and skill requirements (e.g., trade finance specialist, FX/treasury specialist, sanctions/AML specialist, ops/settlement specialist, coverage/relationship). Hiring/training/partnering approach should be specified.Roles can be separate or shared (multiple roles performed by a single individual)','Yes/No','no',NULL,'DFB/IBD');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9947,3826,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KCI','Regular','16.02.01 (C)','(v)','Technology enablers for IFSC workflows','# Technology coverage should include assessment of systems, tools, platforms, and digital enablers required to support IFSC business, incremental to the existing domestic technology.  # The roadmap should identify gaps in current capabilities and define required enhancements, with a focus on improving (but not limited to) turnaround time, customer experience, compliance, and cross-border transaction handling.','Yes/No','no',NULL,'DFB/IBD');
