INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9954,3834,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KCI','Regular','16.02.02 (A)','i','Digital NRI home loan journey with application, document submission, and application status tracking up to sanction stage','# Application, document submission and application tracking, until sanction stage to be provided via digital channels','Yes/No','NO',NULL,'Retail Assets');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9955,3835,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KCI','Regular','16.02.02 (A)','ii','E-signing (digital signing) for sanction of NRI home loans','# E-signing for application submission and processing till sanction stage. # The intent is that NRIs are able to apply for home loans in India without being physically present. Leading private banks allow NRIs to apply for home loans digitally through internet/mobile banking.  # The e-signing facilities allow NRIs to apply and have their home loans sanctioned digitally. However, for disbursement, NRIs have to be either physically present in India, or have a Power of Attorney (PoA) holder act on their behalf to complete the formalities.','Yes/No','NO',NULL,'Retail Assets');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (9956,3836,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KCI','Regular','16.02.02 (A)','iii','Assign a SPOC / RM to each NRI home-loan applicant','# Leading banks assign a SPOC or Relationship Manager (RM) based on location.','Yes/No','NO',NULL,'Retail Assets');
