INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (10012,3894,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KCI/KPI','Regular','16.03.01 (A)','(A)','Does the Bank have dedicated Investor Relations (IR) set-up wth clearly defined ownership and responsibilities incorporating the following points?',NULL,'Formula Count','2',NULL,'FnA-Investor relations');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (10013,3895,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KCI','Regular','16.03.01 (A)','(i)','Separate IR function/team','# “Separate” means IR is defined as a distinct function/mandate with an identifiable team or cell responsible for investor and analyst engagement, disclosures support, IR calendar execution and other IR related activites.  # It may or may not sit within other functions (e.g., Finance/Strategy/Corp Comms), but must have a defined IR mandate (not ad-hoc).','Yes/No','YES',NULL,'FnA-Investor relations');
INSERT INTO "EASE_P1_METRIC" ("ID","ROW_ID","THEME_NO","THEME_NAME","AP_NO","AP_NAME","KCI_KPI","METRIC_TYPE","METRIC_SORT","METRIC_ID_CODE","METRIC_DESC","EXPLANATORY_COMMENTS","EXPECTED_RESPONSE_TYPE","BASELINE","BMO_VERTICAL","BMS_VERTICAL") VALUES (10014,3896,'Theme 04','Excellence','AP16','Capital Efficiency and Global Competitiveness','KCI','Regular','16.03.01 (A)','(ii)','Named IR owner (designation/ role) with primary responsible for IR','# A designated role that owns and is responsible for IR outcomes and coordination. The IR owner may hold another portfolio, but IR must be a primary, explicitly documented responsibility.','Yes/No','YES',NULL,'FnA-Investor relations');
